module LFSR (
    output reg [3:0] out,
    input clk,
    input rst
);
    reg [3:0] out_reg;
    wire feedback;

    assign feedback = ~(out_reg[3] ^ out_reg[2]);
    assign out = out_reg;
    always@(posedge clk or posedge rst) begin
        if(rst) out_reg <= 4'b0; else out_reg <= {out_reg[2:0],feedback};
    end

endmodule
